Item.method_code:
var ids = this.grid.getSelectedItemIds();
ids.forEach(id => {
    var result = aras.IomInnovator.newItem("Method", "h4_DeleteRelHistory");
    result.setProperty("relId", id);
    result.setProperty("relTypeName", this.relationshipTypeName)
    result.apply();
    
    if(result.isError())
    {
        aras.AlertError(result.getErrorString());
        return;
    }
});
parent.onRefresh();
